typedef struct {
    unsigned int start;
    unsigned int end;
    double total_weight;
} LineContribType;

typedef double (*interpolation_method)(double);

LineContribType* calculate_line_contributions(unsigned int line_size, unsigned int src_size, double scale_d, interpolation_method pFilter) {
    if (line_size == 0 || src_size == 0 || scale_d <= 0.0 || pFilter == NULL) {
        return NULL;
    }

    unsigned int filter_width = (unsigned int)(1.0 / scale_d) + 1;
    LineContribType* contribs = (LineContribType*)malloc(line_size * sizeof(LineContribType));
    if (contribs == NULL) {
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; i++) {
        double scaled_x = i / scale_d;
        unsigned int left = (unsigned int)(scaled_x - filter_width / 2.0);
        unsigned int right = (unsigned int)(scaled_x + filter_width / 2.0);
        contribs[i].start = left;
        contribs[i].end = right;
        contribs[i].total_weight = 0.0;

        for (unsigned int j = left; j <= right && j < src_size; j++) {
            double offset = j - scaled_x;
            double weight = pFilter(offset);
            contribs[i].total_weight += weight;
        }

        if (contribs[i].total_weight <= 0.0) {
            free(contribs);
            return NULL;
        }
    }

    return contribs;
}
